// ========== কনফিগারেশন ==========
const DOWNLOAD_DIR = path.join(__dirname, 'downloads');
fs.ensureDirSync(DOWNLOAD_DIR);

// মিডলওয়্যার
app.use(cors());
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

// রেট লিমিট (প্রতি IP থেকে প্রতি 10 মিনিটে 50টি ডাউনলোড)
const limiter = rateLimit({
  windowMs: 10 * 60 * 1000,
  max: 50,
  message: { error: 'Too many requests, please try again later.' }
});
app.use('/download', limiter);

// অ্যাক্টিভ ডাউনলোড ট্র্যাকিং
const activeDownloads = new Map();

// ---------- ইউটিলিটি ফাংশন ----------
function formatFileSize(bytes) {
  if (bytes === 0) return '0 B';
  const k = 1024;
  const sizes = ['B', 'KB', 'MB', 'GB', 'TB'];
  const i = Math.floor(Math.log(bytes) / Math.log(k));
  return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
}

// ডাউনলোড ফাংশন (প্রতিটি রিকোয়েস্টের জন্য আলাদা প্রক্রিয়া, কুকি ব্যবহার করে)
async function startDownload(url, downloadId, options = {}) {
  const {
    quality = 'best',
    isAudioOnly = false,
    embedSubs = false,
    embedThumbnail = false
  } = options;

  const outputTemplate = path.join(DOWNLOAD_DIR, `${downloadId}_%(title)s.%(ext)s`);
  
  // ফরম্যাট নির্বাচন
  let format = 'bestvideo+bestaudio/best';
  if (isAudioOnly) format = 'bestaudio/best';
  else if (quality === '1080p') format = 'bestvideo[height<=1080][ext=mp4]+bestaudio[ext=m4a]/best[height<=1080][ext=mp4]';
  else if (quality === '720p') format = 'bestvideo[height<=720][ext=mp4]+bestaudio[ext=m4a]/best[height<=720][ext=mp4]';
  else if (quality === '480p') format = 'bestvideo[height<=480][ext=mp4]+bestaudio[ext=m4a]/best[height<=480][ext=mp4]';

  const args = [
    '--format', format,
    '--merge-output-format', 'mp4',
    '--output', outputTemplate,
    '--no-playlist',
    '--quiet',
    '--no-warnings',
    '--cookies', COOKIE_FILE   // ← কুকি ফাইল ব্যবহার করা হচ্ছে
  ];
  
  if (isAudioOnly) {
    args.push('--extract-audio', '--audio-format', 'mp3', '--audio-quality', '192K');
  }
  if (embedSubs) {
    args.push('--write-subs', '--write-auto-subs', '--sub-langs', 'en,bn,hi');
  }
  if (embedThumbnail && !isAudioOnly) {
    args.push('--embed-thumbnail');
  }
  args.push(url);

  // স্ট্যাটাস আপডেট ফাংশন
  const updateStatus = (status, progressData = {}) => {
    const current = activeDownloads.get(downloadId) || { status: 'queued', progress: 0 };
    activeDownloads.set(downloadId, {
      ...current,
      status,
      progress: progressData.percent || current.progress,
      downloaded: progressData.downloaded,
      total: progressData.total,
      speed: progressData.speed,
      eta: progressData.eta,
      updatedAt: Date.now(),
      url
    });
  };

  updateStatus('downloading');

  return new Promise((resolve, reject) => {
    const ytProcess = spawn('yt-dlp', args, { env: process.env });
    let stderrBuffer = '';

    ytProcess.stderr.on('data', (data) => {
      const text = data.toString();
      stderrBuffer += text;
      // প্রগ্রেস ডেটা বের করা
      const progressMatch = text.match(/\[download\]\s+(\d+(?:\.\d+)?)%\s+of\s+([\d.]+[KMG]?B)\s+at\s+([\d.]+[KMG]?B\/s)\s+ETA\s+(\d+:\d+)/);
      if (progressMatch) {
        const percent = parseFloat(progressMatch[1]);
        const total = progressMatch[2];
        const speed = progressMatch[3];
        const eta = progressMatch[4];
        updateStatus('downloading', { percent, total, speed, eta });
      }
    });

    ytProcess.on('close', async (code) => {
      if (code === 0) {
        // ডাউনলোড সম্পূর্ণ – ফাইল খোঁজা
        const files = await fs.readdir(DOWNLOAD_DIR);
        const downloadedFile = files.find(f => f.startsWith(downloadId));
        if (downloadedFile) {
          const filePath = path.join(DOWNLOAD_DIR, downloadedFile);
          const stats = await fs.stat(filePath);
          updateStatus('completed', { percent: 100, total: formatFileSize(stats.size) });
          resolve({ filePath, fileName: downloadedFile, size: stats.size });
        } else {
          reject(new Error('Downloaded file not found'));
        }
      } else {
        reject(new Error(`yt-dlp exited with code ${code}\n${stderrBuffer}`));
      }
    });

    ytProcess.on('error', (err) => {
      reject(err);
    });
  });
}

// ========== ওয়েব এন্ডপয়েন্ট ==========

// হোম পেজ (সহজ ফর্ম)
