// ডাউনলোড রিকোয়েস্ট
app.post('/download', async (req, res) => {
  const { url, quality = 'best', audioOnly = false, subs = false, thumb = false } = req.body;
  if (!url) return res.status(400).json({ error: 'URL is required' });

  const downloadId = uuidv4();
  const clientIp = req.ip;

  // ব্যাকগ্রাউন্ডে ডাউনলোড শুরু করা (নন-ব্লকিং)
  startDownload(url, downloadId, {
    quality,
    isAudioOnly: audioOnly === 'true' || audioOnly === true,
    embedSubs: subs === 'true',
    embedThumbnail: thumb === 'true'
  }).then(async (result) => {
    // ডাউনলোড সম্পূর্ণ – ফাইল ইউআরএল তৈরি
    const fileUrl = `/files/${downloadId}/${encodeURIComponent(result.fileName)}`;
    console.log(`✅ Download ${downloadId} completed for ${url} from ${clientIp}`);
    // (ঐচ্ছিক) আপনি চাইলে এখানে ওয়েবহুক বা নোটিফিকেশন পাঠাতে পারেন
  }).catch(err => {
    console.error(`❌ Download ${downloadId} failed:`, err.message);
    activeDownloads.set(downloadId, { status: 'failed', error: err.message, url });
  });

  res.json({
    success: true,
    downloadId,
    statusUrl: `/status/${downloadId}`,
    message: 'ডাউনলোড শুরু হয়েছে। স্ট্যাটাস চেক করতে statusUrl ব্যবহার করুন।'
  });
});

// স্ট্যাটাস চেক
app.get('/status/:id', (req, res) => {
  const id = req.params.id;
  const status = activeDownloads.get(id);
  if (!status) return res.json({ status: 'not_found', message: 'No such download or expired.' });
  res.json(status);
});

// ডাউনলোড ফাইল সার্ভ করা
app.get('/files/:id/:filename', async (req, res) => {
  const { id, filename } = req.params;
  const filePath = path.join(DOWNLOAD_DIR, filename);
  if (!filename.startsWith(id) || !await fs.pathExists(filePath)) {
    return res.status(404).send('File not found');
  }
  res.download(filePath, filename);
});

// অ্যাক্টিভ ডাউনলোডের তালিকা (মনিটরিং)
app.get('/active', (req, res) => {
  const active = Array.from(activeDownloads.entries()).map(([id, data]) => ({
    id,
    status: data.status,
    progress: data.progress,
    url: data.url,
    updatedAt: data.updatedAt
  }));
  res.json(active);
});

// সার্ভার চালু
app.listen(PORT, () => {
  console.log(`🚀 Web Downloader Bot is running on port ${PORT}`);
  console.log(`🍪 Cookies file loaded: ${COOKIE_FILE}`);
  console.log(`💾 Download directory: ${DOWNLOAD_DIR}`);
});
